import { get, handleApiError } from '@helpers/httpClient';

import {
  mapHikingUserPositionToFront,
  mapHikingWithFriendToFront,
} from '../@mappers/hikingWithFriend.mapper';
import {
  IHikingUserPositionsStatDTO,
  IHikingWithFriendDTO,
} from '../@types/DTO/hikingWithFriend.dto.types';
import { IHikingUserPositionStat, IHikingWithFriend } from '../@types/hikingWithFriend.types';

export const getHikingListForUserOrFriend = async (
  criteria: { user: number } | { friend: number },
): Promise<IHikingWithFriend[]> => {
  const res = await get('/ajax/hiking/user.php', criteria).then<IHikingWithFriendDTO[]>(
    handleApiError,
  );
  return res.map(mapHikingWithFriendToFront);
};

export const getUserPositionsStat = async (
  criteria: { id_user?: number } = {},
): Promise<IHikingUserPositionStat[]> => {
  const res = await get('/ajax/hiking/user_positions.php', criteria).then<
    IHikingUserPositionsStatDTO[]
  >(handleApiError);
  return res.map(mapHikingUserPositionToFront);
};
